{
  "spells": [
    {
      "id": "spell_water_13",
      "theory": "流幕术将水汽汇聚于树脂刻痕，形成循环水帘遮挡通道。施法时水帘持续流动，发出稳定水声，暴露施法者方位。水帘不阻挡实体，仅模糊视线，无法隔绝气味或声音。",
      "casting": "手持树脂块，在水源旁画波浪符文，同时以掌缘缓慢推入魔力，待水帘升起即停。",
      "failure": "水帘无法成形，只溅起水花弄湿地面；或水幕突然崩塌，发出巨响并暴露位置。",
      "counters": [
        "用强风吹散水帘，使其无法维持幕状。",
        "投掷吸水性材料如干布，吸附水汽破坏循环。"
      ],
      "socialConsequences": "在河谷乡约中，未经许可在共有水源处施放流幕术可能被视为扰乱用水，需经同意。城市公会要求施法者登记，避免遮挡消防通道。港口则严禁在码头区使用，以防掩盖走私或引发航运事故，违者重罚。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "crime"
      },
      "proficiencyEffects": [
        "初学时常需反复调整符文，水帘易波动。",
        "熟练后水帘稳定，能持续遮挡一处通道。",
        "高手可控制水帘厚度，减少水声外传。",
        "大师能让水帘几近无声，但仍无法完全消音。"
      ]
    },
    {
      "id": "spell_water_14",
      "theory": "潮压阵利用树脂为媒介，在狭小水域内制造均匀压力。压力只作用于水中，站在区域内的人均受影响，但不会直接造成伤害，仅阻碍行动。压力随距离衰减，范围有限。",
      "casting": "将树脂投入水中，双手结印并低声念诵，待水面出现环形波纹即完成。",
      "failure": "压力未能均匀分布，导致局部水压过强，可能掀翻小型船只或使人跌倒。",
      "counters": [
        "离开水域即可摆脱压力影响。",
        "用长杆破坏水面符文，中断压力循环。"
      ],
      "socialConsequences": "河谷乡约允许在私有水域施放，但需确保不波及他人。城市公会要求提前申请许可，防止影响航运或渔业。港口视为重罪，因可能引发事故或货损，港务会追究责任。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "crime"
      },
      "proficiencyEffects": [
        "新手压力不稳，容易误伤自身。",
        "熟练者能控制压力范围，避免波及无关者。",
        "高手可精确调节压力，仅限制行动而不致伤。",
        "大师能瞬间布阵，但仍需水域存在。"
      ]
    }
  ]
}
